src/app.css.source:
@import 'tailwindcss';
@import './lib/styles/pretendard.css';

@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/* The track conveys theme state; the outer hit target stays clear while idle. */
.lc-theme-switch {
	background: transparent;
	border-color: transparent;
	color: var(--lc-text-secondary);
	box-shadow: none;
}

@media (hover: hover) and (pointer: fine) {
	.lc-theme-switch:hover {
		background: var(--lc-surface-hover);
		color: var(--lc-text-primary);
	}
}

.lc-theme-switch-track {
	position: relative;
	display: inline-flex;
	align-items: center;
	width: 2.9rem;
	height: 1.6rem;
	padding: 0.12rem;
	border-radius: 9999px;
	background: rgba(148, 163, 184, 0.32);
	transition: background-color 180ms ease;
}

.lc-theme-switch-track.is-dark {
	background: #2563eb;
}

.lc-theme-switch-thumb {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 1.35rem;
	height: 1.35rem;
	border-radius: 9999px;
	background: var(--lc-surface-primary);
	color: #f59e0b;
	box-shadow: 0 6px 18px rgba(15, 23, 42, 0.18);
	transform: translateX(0);
	transition:
		transform 180ms ease,
		background-color 180ms ease,
		color 180ms ease;
}

.lc-theme-switch-thumb.is-dark {
	transform: translateX(1.28rem);
	color: #a5f3fc;
}

.svg-inline--fa {
	display: inline-block;
	height: 1em;
	overflow: visible;
	vertical-align: -0.125em;
}

.svg-inline--fa.fa-fw {
	width: 1.25em;
}

:root {
	--lc-body-bg: #ffffff;
	--lc-content-card-bg: var(--lc-surface-muted);
	--lc-content-card-chip-bg: var(--lc-surface-primary);
	--lc-semantic-result-bg: var(--lc-surface-muted);
	--lc-semantic-result-chip-bg: var(--lc-surface-primary);
	--lc-loading-backdrop: color-mix(in srgb, var(--lc-body-bg) 55%, transparent);
	--lc-page-bg: #ffffff;
	--lc-header-gradient: #ffffff;
	--lc-surface-primary: #ffffff;
	--lc-surface-elevated: #ffffff;
	--lc-surface-muted: #f3f3f1;
	--lc-surface-inset: #f8f8f6;
	--lc-surface-hover: #ededeb;
	--lc-surface-accent: #f0f1ef;
	--lc-border-soft: #d7d8d4;
	--lc-border-strong: #a6a8a3;
	--lc-control-border: #858881;
	--lc-text-primary: #242624;
	--lc-text-secondary: #50544f;
	--lc-text-muted: #626660;
	--lc-text-dim: #686c66;
	--lc-text-accent: #1d4ed8;
	--lc-status-success: #15803d;
	--lc-status-warning: #b45309;
	--lc-status-error: #b91c1c;
	--lc-progress-color: #c2410c;
	--lc-shadow-soft: none;
	--lc-shadow-card: none;
	--lc-home-kicker-bg: var(--lc-surface-muted);
	--lc-home-kicker-border: var(--lc-border-soft);
	--lc-home-kicker-text: var(--lc-text-secondary);
	--lc-home-signal-bg: var(--lc-surface-muted);
	--lc-home-signal-border: var(--lc-border-soft);
	--lc-home-signal-shadow: none;
	--lc-home-signal-glow: transparent;
	--lc-home-search-bg: var(--lc-surface-primary);
	--lc-home-search-border: var(--lc-border-soft);
	--lc-home-search-shadow: none;
	--lc-home-chip-bg: var(--lc-surface-primary);
	--lc-home-chip-border: var(--lc-border-soft);
	--lc-home-proof-bg: var(--lc-surface-muted);
	--lc-home-proof-border: var(--lc-border-soft);
}

html[data-theme='dark'] {
	--lc-content-card-bg: var(--lc-surface-primary);
	--lc-content-card-chip-bg: var(--lc-surface-muted);
	--lc-semantic-result-bg: var(--lc-surface-primary);
	--lc-semantic-result-chip-bg: var(--lc-surface-muted);
	--lc-body-bg: #242526;
	--lc-page-bg: #242526;
	--lc-header-gradient: #28292a;
	--lc-surface-primary: #2d2e2f;
	--lc-surface-elevated: #303132;
	--lc-surface-muted: #333435;
	--lc-surface-inset: #28292a;
	--lc-surface-hover: #3c3d3e;
	--lc-surface-accent: #393b3c;
	--lc-border-soft: #505253;
	--lc-border-strong: #808283;
	--lc-control-border: #8b8f88;
	--lc-text-primary: #f1f2ee;
	--lc-text-secondary: #d1d3ce;
	--lc-text-muted: #babdb7;
	--lc-text-dim: #adb1aa;
	--lc-text-accent: #9bb9d9;
	--lc-status-success: #bfe8d1;
	--lc-status-warning: #fde68a;
	--lc-status-error: #fca5a5;
	--lc-progress-color: #fb923c;
	--lc-shadow-soft: none;
	--lc-shadow-card: none;
	--lc-home-kicker-bg: var(--lc-surface-muted);
	--lc-home-kicker-border: var(--lc-border-soft);
	--lc-home-kicker-text: var(--lc-text-secondary);
	--lc-home-signal-bg: var(--lc-surface-muted);
	--lc-home-signal-border: var(--lc-border-soft);
	--lc-home-signal-shadow: none;
	--lc-home-signal-glow: transparent;
	--lc-home-search-bg: var(--lc-surface-primary);
	--lc-home-search-border: var(--lc-border-soft);
	--lc-home-search-shadow: none;
	--lc-home-chip-bg: var(--lc-surface-primary);
	--lc-home-chip-border: var(--lc-border-soft);
	--lc-home-proof-bg: var(--lc-surface-muted);
	--lc-home-proof-border: var(--lc-border-soft);
}

html {
	scroll-behavior: auto;
}

/* A palette swap must not interpolate foreground and surface colors through low contrast. */
html[data-theme-changing] *,
html[data-theme-changing] *::before,
html[data-theme-changing] *::after {
	transition-property: transform, opacity !important;
}

/* Keep focus rings inside clipped list containers and align pointer/keyboard feedback. */
.lc-main .lc-card-list-link:is(:hover, :focus-visible) {
	background: var(--lc-surface-hover);
}

.lc-main .lc-card-list-link:is(:hover, :focus-visible) .lc-list-title {
	color: var(--lc-text-accent);
}

.lc-main .lc-card-list-link:focus-visible {
	outline-offset: -3px;
}

[class*='rounded-'],
[class*='rounded'] {
	border-radius: 0.5rem !important;
}

[class*='shadow-'],
[class*='shadow'],
[class*='hover:shadow'],
[class*='focus:ring-'],
[class*='focus-visible:ring-'],
[class*='backdrop-blur'] {
	box-shadow: none !important;
	backdrop-filter: none !important;
}

body {
	font-family:
		'Pretendard', 'Inter', 'Noto Sans KR', 'Apple SD Gothic Neo', 'Malgun Gothic', 'Segoe UI',
		'Helvetica Neue', Arial, system-ui, sans-serif, 'Apple Color Emoji', 'Noto Color Emoji';
	margin: 0;
	padding: 0;
	min-height: 100vh;
	background: var(--lc-body-bg);
	color: var(--lc-text-primary);
}

.lc-page-shell {
	min-height: 100vh;
	background: var(--lc-page-bg);
}

.lc-defer-render {
	content-visibility: auto;
	contain-intrinsic-size: auto 720px;
}

.lc-defer-render-sm {
	content-visibility: auto;
	contain-intrinsic-size: auto 280px;
}

.lc-defer-render-lg {
	content-visibility: auto;
	contain-intrinsic-size: auto 1080px;
}

:root {
	--lc-home-hero-header-offset: 8.5rem;
}

.lc-panel-hero,
.lc-panel-card,
.lc-panel-subtle,
.lc-panel-inset {
	/* Deferred panels must change foreground and background together when the theme changes. */
	transition:
		border-color 180ms ease,
		box-shadow 180ms ease;
}

.lc-panel-hero {
	background: var(--lc-surface-elevated);
	border-color: var(--lc-border-soft);
	box-shadow: var(--lc-shadow-soft);
	border-radius: 1.25rem !important;
}

html[data-theme='dark'] .lc-panel-hero {
	background: var(--lc-surface-elevated);
	border-color: var(--lc-border-soft);
}

.lc-loading-shell {
	border-radius: 1rem !important;
	overflow: hidden;
}

.lc-loading-shell * {
	border-radius: inherit;
}

.lc-home-hero {
	position: relative;
	overflow: hidden;
	min-height: calc(100svh - var(--lc-home-hero-header-offset));
	display: flex;
	align-items: center;
	isolation: isolate;
}

.lc-home-hero-content {
	width: 100%;
	min-block-size: clamp(39rem, 74svh, 47rem);
}

.lc-home-hero::after {
	content: '';
	position: absolute;
	inset: -6rem auto auto -6rem;
	width: 20rem;
	height: 20rem;
	border-radius: 9999px;
	pointer-events: none;
	filter: blur(12px);
	z-index: -1;
}

.lc-home-hero::before {
	content: '';
	position: absolute;
	inset: auto -8rem -8rem auto;
	width: 18rem;
	height: 18rem;
	border-radius: 9999px;
	pointer-events: none;
	filter: blur(10px);
	z-index: -1;
}

.lc-home-kicker {
	background: var(--lc-home-kicker-bg);
	border: 1px solid var(--lc-home-kicker-border);
	color: var(--lc-home-kicker-text);
	box-shadow: none;
}

.lc-home-pill {
	background: var(--lc-surface-muted);
	border: 1px solid var(--lc-border-soft);
	color: var(--lc-text-secondary);
}

.lc-home-heading-accent {
	color: color-mix(in srgb, var(--lc-text-accent) 84%, var(--lc-text-primary) 16%);
}

.lc-home-proof-note {
	background: var(--lc-home-proof-bg);
	border: 1px solid var(--lc-home-proof-border);
	color: var(--lc-text-secondary);
	backdrop-filter: blur(10px);
}

.lc-home-stat {
	background: color-mix(in srgb, var(--lc-surface-primary) 78%, transparent);
	border-color: color-mix(in srgb, var(--lc-border-soft) 82%, rgba(148, 163, 184, 0.08) 18%);
	backdrop-filter: blur(14px);
}

.lc-home-stat-icon {
	color: var(--lc-text-secondary);
}

.lc-home-search-card {
	background: var(--lc-home-search-bg);
	border-color: var(--lc-home-search-border);
	box-shadow: none;
	backdrop-filter: none;
}

.lc-home-search-shell {
	contain: layout paint;
	min-block-size: 19rem;
}

.lc-home-search-form {
	min-block-size: 5.5rem;
}

.lc-home-search-submit {
	min-inline-size: 8.5rem;
}

.lc-home-search-submit-inner {
	position: relative;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-inline-size: 4.75rem;
}

.lc-home-search-submit-label,
.lc-home-search-submit-spinner {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	transition: opacity 140ms ease;
}

.lc-home-search-submit-spinner {
	position: absolute;
	inset: 0;
}

.lc-home-search-loading-shell {
	min-block-size: 0.375rem;
	opacity: 0;
	transition: opacity 140ms ease;
}

.lc-home-search-loading-shell.is-active {
	opacity: 1;
}

.lc-home-signal-grid {
	display: grid;
	grid-template-columns: repeat(1, minmax(0, 1fr));
	gap: 0.75rem;
}

.lc-home-signal-card {
	position: relative;
	overflow: hidden;
	border-radius: 0.5rem;
	padding: 0.875rem 1rem;
	border: 1px solid var(--lc-home-signal-border);
	background: var(--lc-home-signal-bg);
	box-shadow: none;
	backdrop-filter: none;
	transition: translate 200ms ease;
}

.lc-home-signal-card::after {
	content: '';
	position: absolute;
	inset: auto -28% -55% auto;
	width: 7.5rem;
	height: 7.5rem;
	border-radius: 9999px;
	background: radial-gradient(circle, var(--lc-home-signal-glow) 0%, transparent 72%);
	pointer-events: none;
}

.lc-home-signal-card:hover {
	transform: none;
	border-color: color-mix(in srgb, var(--lc-home-signal-border) 72%, var(--lc-text-accent) 28%);
	box-shadow: none;
}

.lc-home-signal-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.75rem;
	margin-bottom: 0.5rem;
}

.lc-home-signal-icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	color: var(--lc-text-accent);
}

.lc-home-signal-tag {
	font-size: 0.69rem;
	font-weight: 700;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--lc-text-muted);
}

.lc-home-signal-value {
	margin: 0;
	font-size: 1.04rem;
	line-height: 1.35;
	font-weight: 700;
	color: var(--lc-text-primary);
}

.lc-home-signal-desc {
	margin: 0.25rem 0 0;
	font-size: 0.79rem;
	line-height: 1.4;
	color: var(--lc-text-secondary);
}

@media (min-width: 640px) {
	.lc-home-signal-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
}

@media (max-width: 639px) {
	:root {
		--lc-home-hero-header-offset: 7.5rem;
	}

	.lc-home-hero {
		min-height: calc(100svh - var(--lc-home-hero-header-offset));
	}

	.lc-home-hero-content {
		min-block-size: 43rem;
	}

	.lc-home-search-shell {
		min-block-size: 21.5rem;
	}

	.lc-home-search-form {
		min-block-size: 8.5rem;
	}
}

.lc-home-search-badge {
	background: color-mix(in srgb, var(--lc-surface-accent) 72%, white 28%);
	color: var(--lc-text-accent);
	border: 1px solid color-mix(in srgb, var(--lc-border-strong) 60%, transparent);
}

.lc-home-search-input {
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

/* Pinned admin notice chip: deliberately low contrast (quiet border, muted
   text) so it reads as a special status marker, not another interactive
   keyword chip — the bullhorn icon carries the distinction instead. */
.lc-home-notice-chip {
	background: transparent;
	border: 1px solid var(--lc-border-soft);
	color: var(--lc-text-muted);
	transition:
		background-color 180ms ease,
		color 180ms ease;
}

.lc-home-notice-chip:hover {
	background: var(--lc-surface-hover);
	color: var(--lc-text-secondary);
}

/* Urgent admin notice banner: the one deliberately loud element in the UI —
   solid red bar directly under the sticky header so a `긴급` notice is impossible
   to miss on every page. */
.lc-urgent-banner {
	background: var(--lc-surface-muted);
	color: var(--lc-text-primary);
	border-color: var(--lc-border-soft);
}

html[data-theme='dark'] .lc-urgent-banner {
	background: var(--lc-surface-muted);
	color: var(--lc-text-primary);
	border-color: var(--lc-border-soft);
}

.lc-urgent-banner a {
	color: inherit;
	transition: filter 180ms ease;
}

.lc-urgent-banner a:hover {
	filter: brightness(1.08);
}

.lc-urgent-banner a:focus-visible {
	outline: 2px solid #fff;
	outline-offset: -4px;
	border-radius: 0.25rem;
}

.lc-urgent-badge {
	display: inline-flex;
	align-items: center;
	background: #fff;
	color: #b91c1c;
	font-size: 0.7rem;
	font-weight: 800;
	letter-spacing: 0.06em;
	padding: 0.15rem 0.5rem;
	border-radius: 999px;
}

html[data-theme='dark'] .lc-urgent-badge {
	background: #fef2f2;
	color: #7f1d1d;
}

.lc-home-search-chip {
	background: var(--lc-home-chip-bg);
	border: 1px solid var(--lc-home-chip-border);
	color: var(--lc-text-secondary);
	transition:
		background-color 180ms ease,
		border-color 180ms ease,
		color 180ms ease,
		transform 180ms ease;
}

.lc-home-search-chip:hover {
	background: color-mix(in srgb, var(--lc-surface-accent) 80%, white 20%);
	border-color: color-mix(in srgb, var(--lc-border-strong) 82%, transparent);
	color: var(--lc-text-primary);
	transform: translateY(-1px);
}

.lc-home-search-foot {
	background: color-mix(in srgb, var(--lc-surface-inset) 86%, white 14%);
	border-color: var(--lc-border-soft);
}

.lc-home-foot-icon {
	color: var(--lc-text-accent);
}

.lc-panel-card {
	background: var(--lc-surface-primary);
	border-color: var(--lc-border-soft);
	box-shadow: none;
	border-radius: 0.5rem;
}

/* Content surfaces are distinct from the page; menus and open reading areas stay independent. */
.lc-main .lc-content-card:not(.lc-banner-warning) {
	background: var(--lc-content-card-bg);
}

.lc-main
	.lc-content-card:not(.lc-banner-warning)
	:is(.lc-chip-blue, .lc-chip-muted, .lc-chip-purple) {
	background: var(--lc-content-card-chip-bg);
}

.lc-panel-subtle {
	background: var(--lc-surface-muted);
	border-color: var(--lc-border-soft);
	box-shadow: none;
}

.lc-panel-inset {
	background: var(--lc-surface-inset);
	border-color: var(--lc-border-soft);
	border-radius: 0.5rem;
}

.lc-text-primary {
	color: var(--lc-text-primary);
}

.lc-text-secondary {
	color: var(--lc-text-secondary);
}

.lc-text-muted {
	color: var(--lc-text-muted);
}

.lc-text-dim {
	color: var(--lc-text-dim);
}

.lc-text-accent {
	color: var(--lc-text-accent);
}

.lc-link {
	color: var(--lc-text-accent);
	text-decoration-line: underline;
	text-decoration-thickness: 1px;
	text-decoration-color: color-mix(in srgb, currentColor 45%, transparent);
	text-underline-offset: 0.2em;
	transition:
		color 160ms ease,
		text-decoration-color 160ms ease;
}

.lc-link:hover,
.lc-link:focus-visible {
	text-decoration-color: currentColor;
}

.lc-text-success {
	color: #15803d;
}

.lc-text-info {
	color: #0369a1;
}

.lc-text-warning {
	color: #b45309;
}

.lc-diff-removed,
.lc-diff-added {
	border-radius: 0.25rem;
	padding: 0 0.125rem;
	font-weight: 700;
	box-decoration-break: clone;
	-webkit-box-decoration-break: clone;
}

.lc-diff-removed {
	background: #dc2626;
	color: #ffffff;
	box-shadow: inset 0 0 0 1px rgba(127, 29, 29, 0.72);
}

.lc-diff-added {
	background: #15803d;
	color: #ffffff;
	box-shadow: inset 0 0 0 1px rgba(21, 128, 61, 0.72);
}

html[data-theme='dark'] .lc-diff-removed {
	background: #fca5a5;
	color: #111827;
	box-shadow: inset 0 0 0 1px rgba(248, 113, 113, 0.58);
}

html[data-theme='dark'] .lc-diff-added {
	background: #86efac;
	color: #111827;
	box-shadow: inset 0 0 0 1px rgba(74, 222, 128, 0.58);
}

.lc-text-danger {
	color: #b91c1c;
}

.lc-text-purple {
	color: #6d28d9;
}

.lc-text-on-accent {
	color: #fff;
}

.lc-divider-soft {
	background: var(--lc-border-soft);
}

.lc-overlay-backdrop {
	background: rgba(15, 23, 42, 0.32);
}

.lc-hover-subtle-bg:hover {
	background: color-mix(in srgb, var(--lc-surface-muted) 82%, transparent);
}

.lc-ai-badge-hoverable:hover {
	background: var(--lc-surface-hover);
}

.lc-step-chip {
	background: #2563eb;
	color: #fff;
}

.lc-step-chip-success {
	background: #16a34a;
	color: #fff;
}

.lc-dot-warning {
	background: #f59e0b;
}

.lc-dot-success {
	background: #16a34a;
}

.lc-notice-border-active {
	border-left-color: #34d399;
}

.lc-notice-border-done {
	border-left-color: color-mix(in srgb, var(--lc-border-soft) 88%, #94a3b8 12%);
}

.lc-inline-code {
	background: var(--lc-surface-muted);
	color: var(--lc-text-secondary);
}

.lc-loading-track {
	background: var(--lc-surface-accent);
	border-radius: 9999px;
	overflow: hidden;
}

.lc-loading-fill {
	background: var(--lc-text-accent);
	border-radius: 9999px;
}

.lc-button-neutral {
	background: var(--lc-surface-primary);
	border-color: var(--lc-border-soft);
	color: var(--lc-text-secondary);
	box-shadow: none;
	border-radius: 0.5rem;
	transition:
		background-color 180ms ease,
		border-color 180ms ease,
		color 180ms ease;
}

.lc-button-neutral:hover {
	background: var(--lc-surface-hover);
	border-color: color-mix(in srgb, var(--lc-border-soft) 72%, var(--lc-text-accent) 28%);
	color: var(--lc-text-primary);
}

.lc-button-secondary {
	background: var(--lc-surface-primary);
	border-color: var(--lc-border-soft);
	color: var(--lc-text-secondary);
	box-shadow: none;
	border-radius: 0.5rem;
	transition:
		background-color 180ms ease,
		border-color 180ms ease,
		color 180ms ease;
}

.lc-button-secondary:hover {
	background: var(--lc-surface-hover);
	border-color: color-mix(in srgb, var(--lc-border-soft) 72%, var(--lc-text-accent) 28%);
	color: var(--lc-text-primary);
}

.lc-button-primary {
	background: #1d4ed8;
	color: #fff;
	box-shadow: none;
	border-radius: 0.5rem;
	/* Deferred controls must not transition from the UA background on first reveal. */
	transition: transform 180ms ease;
}

.lc-button-primary:hover {
	background: #1e40af;
	box-shadow: none;
}

.lc-toggle-track-off {
	background: rgba(148, 163, 184, 0.34);
}

.lc-toggle-track-on {
	background: #1d4ed8;
}

.lc-pagination-btn {
	background: var(--lc-surface-primary);
