/* Soft fade-in animation. */
@keyframes fadeIn {
	from {
		opacity: 0;
		transform: translateY(20px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

.lc-animate-fade-in {
	animation: fadeIn 0.6s ease-out;
}

/* Soft hover lift effect. */
.lc-hover-lift {
	transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.lc-hover-lift:hover {
	transform: translateY(-2px);
	box-shadow:
		0 20px 25px -5px rgba(0, 0, 0, 0.1),
		0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

/* NProgress custom styles. */
#nprogress {
	--lc-progress-color: #1d4ed8;
	pointer-events: none;
}

html[data-theme='dark'] #nprogress {
	--lc-progress-color: #60a5fa;
}

#nprogress .bar {
	position: fixed;
	top: 0;
	left: 0;
	width: 100%;
	background: var(--lc-progress-color) !important;
	height: 2px !important;
	z-index: 99999 !important;
}

#nprogress .peg {
	display: block;
	position: absolute;
	right: 0;
	width: 100px;
	height: 100%;
	opacity: 1;
	transform: rotate(3deg) translate(0, -4px);
	box-shadow:
		0 0 10px var(--lc-progress-color),
		0 0 5px var(--lc-progress-color) !important;
}

#nprogress .spinner-icon {
	border-top-color: var(--lc-progress-color) !important;
	border-left-color: var(--lc-progress-color) !important;
}

/* Shared loading slide effect. */
.lc-loading-slide {
	animation: lc-loading-slide 1.15s ease-in-out infinite;
}

@keyframes lc-loading-slide {
	0% {
		transform: translateX(-120%);
	}
	100% {
		transform: translateX(320%);
	}
}

/* Magic-wand glint on the semantic search button while a query is in flight. */
.lc-wand-glint {
	animation: lc-wand-glint 1.5s ease-in-out infinite;
	transform-origin: 70% 30%;
}

@keyframes lc-wand-glint {
	0%,
	100% {
		transform: rotate(-8deg) scale(0.94);
		opacity: 0.85;
	}
	50% {
		transform: rotate(10deg) scale(1.12);
		opacity: 1;
	}
}

@media (prefers-reduced-motion: reduce) {
	.lc-wand-glint {
		animation: none;
	}
}
/* A destination wash stays behind the text without changing row geometry. */
.lc-comment-target {
	isolation: isolate;
}
.lc-comment-target::before {
	position: absolute;
	z-index: -1;
	inset: 0 -0.75rem;
	border-inline-start: 3px solid var(--lc-text-accent);
	background: color-mix(in srgb, var(--lc-text-accent) 9%, transparent);
	opacity: 0;
	pointer-events: none;
	content: '';
	transition: opacity 600ms ease-out;
}
.lc-comment-target.lc-comment-highlight::before {
	opacity: 1;
	transition-duration: 180ms;
}
@media (prefers-reduced-motion: reduce) {
	.lc-comment-target::before,
	.lc-comment-target.lc-comment-highlight::before {
		transition: none;
	}
}

@media (prefers-reduced-motion: reduce) {
	* {
		scroll-behavior: auto !important;
		animation-duration: 0.01ms !important;
		animation-iteration-count: 1 !important;
		transition-duration: 0.01ms !important;
	}
}

/* ── Timeline ────────────────────────────────────────────────────────── */

.lc-timeline {
	position: relative;
	padding-left: 1.5rem;
}

/* Vertical connecting line */
.lc-timeline::before {
	content: '';
	position: absolute;
	left: 0.4375rem;
	top: 0;
	bottom: 0;
	width: 2px;
	background: linear-gradient(to bottom, var(--lc-border-soft), rgba(148, 163, 184, 0.2));
}

.lc-timeline-item {
	position: relative;
	padding-bottom: 0.75rem;
}

.lc-timeline-item:last-child {
	padding-bottom: 0;
}

/* Timeline dot */
.lc-timeline-dot {
	position: absolute;
	left: -1.0625rem;
	top: 0.75rem;
	width: 0.625rem;
	height: 0.625rem;
	border-radius: 9999px;
	background: var(--lc-text-dim);
	border: 2px solid var(--lc-surface-primary);
	box-shadow: 0 0 0 2px var(--lc-border-soft);
	transition: all 0.2s ease;
}

/* Emphasized event (invalidated) */
.lc-timeline-item--emphasis .lc-timeline-dot {
	background: #f59e0b;
	box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.3);
	width: 0.75rem;
	height: 0.75rem;
	left: -1.125rem;
	top: 0.6875rem;
}

/* Active/current revision dot */
.lc-timeline-item--active .lc-timeline-dot {
	background: #10b981;
	box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.3);
	width: 0.75rem;
	height: 0.75rem;
	left: -1.125rem;
	top: 0.6875rem;
}

/* Hover effect on timeline items */
.lc-timeline-item:hover .lc-timeline-dot {
	transform: scale(1.2);
	box-shadow: 0 0 0 3px var(--lc-border-soft);
}

.lc-timeline-item--active:hover .lc-timeline-dot {
	box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.4);
}

.lc-timeline-item--emphasis:hover .lc-timeline-dot {
	box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.4);
}

/* Dark mode timeline */
html[data-theme='dark'] .lc-timeline::before {
	background: linear-gradient(to bottom, rgba(100, 116, 139, 0.4), rgba(71, 85, 105, 0.2));
}

html[data-theme='dark'] .lc-timeline-dot {
	background: rgba(100, 116, 139, 0.8);
	border-color: rgba(30, 41, 59, 0.9);
	box-shadow: 0 0 0 2px rgba(100, 116, 139, 0.3);
}

html[data-theme='dark'] .lc-timeline-item--emphasis .lc-timeline-dot {
	background: #fbbf24;
	box-shadow: 0 0 0 2px rgba(251, 191, 36, 0.3);
}

html[data-theme='dark'] .lc-timeline-item--active .lc-timeline-dot {
	background: #34d399;
	box-shadow: 0 0 0 2px rgba(52, 211, 153, 0.3);
}

/* Responsive timeline adjustments */
@media (max-width: 640px) {
	.lc-timeline {
		padding-left: 1.25rem;
	}

	.lc-timeline::before {
		left: 0.375rem;
	}

	.lc-timeline-dot {
		left: -0.875rem;
		width: 0.5rem;
		height: 0.5rem;
		top: 0.8125rem;
	}

	.lc-timeline-item--emphasis .lc-timeline-dot,
	.lc-timeline-item--active .lc-timeline-dot {
		left: -0.9375rem;
		width: 0.625rem;
		height: 0.625rem;
		top: 0.75rem;
	}

	.lc-timeline-item--compare-from .lc-timeline-dot,
	.lc-timeline-item--compare-to .lc-timeline-dot {
		left: -0.9375rem;
		width: 0.625rem;
		height: 0.625rem;
		top: 0.75rem;
	}
}

/* ── Compare Mode ────────────────────────────────────────────────────── */

/* Compare base (from) - Blue highlight */
.lc-timeline-item--compare-from {
	background: rgba(59, 130, 246, 0.08);
	border-radius: 0.75rem;
	margin-left: -0.5rem;
	margin-right: -0.5rem;
	padding-left: 0.5rem;
	padding-right: 0.5rem;
}

.lc-timeline-item--compare-from .lc-timeline-dot {
	background: #3b82f6;
	box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
	width: 0.75rem;
	height: 0.75rem;
	left: -1.125rem;
	top: 0.6875rem;
}

/* Compare target (to) - Green highlight */
.lc-timeline-item--compare-to {
	background: rgba(16, 185, 129, 0.08);
	border-radius: 0.75rem;
	margin-left: -0.5rem;
	margin-right: -0.5rem;
	padding-left: 0.5rem;
	padding-right: 0.5rem;
}

.lc-timeline-item--compare-to .lc-timeline-dot {
	background: #10b981;
	box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.3);
	width: 0.75rem;
	height: 0.75rem;
	left: -1.125rem;
	top: 0.6875rem;
}

/* Compare range indicator - line between from and to */
.lc-timeline-item--compare-from + .lc-timeline-item--compare-to::before,
.lc-timeline-item--compare-to + .lc-timeline-item--compare-from::before {
	content: '';
	position: absolute;
	left: 0;
	right: 0;
	top: -0.375rem;
	height: 0.25rem;
	background: linear-gradient(90deg, rgba(59, 130, 246, 0.4), rgba(16, 185, 129, 0.4));
	border-radius: 0.125rem;
}

/* Hover effects for compare items */
.lc-timeline-item--compare-from:hover {
	background: rgba(59, 130, 246, 0.12);
}

.lc-timeline-item--compare-to:hover {
	background: rgba(16, 185, 129, 0.12);
}

.lc-timeline-item--compare-from:hover .lc-timeline-dot {
	box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.4);
}

.lc-timeline-item--compare-to:hover .lc-timeline-dot {
	box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.4);
}

/* Dark mode compare styles */
html[data-theme='dark'] .lc-timeline-item--compare-from {
	background: rgba(59, 130, 246, 0.15);
}

html[data-theme='dark'] .lc-timeline-item--compare-to {
	background: rgba(16, 185, 129, 0.15);
}

html[data-theme='dark'] .lc-timeline-item--compare-from .lc-timeline-dot {
	background: #60a5fa;
	box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.4);
}

html[data-theme='dark'] .lc-timeline-item--compare-to .lc-timeline-dot {
	background: #34d399;
	box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.4);
}

html[data-theme='dark'] .lc-timeline-item--compare-from:hover {
	background: rgba(59, 130, 246, 0.2);
}

html[data-theme='dark'] .lc-timeline-item--compare-to:hover {
	background: rgba(16, 185, 129, 0.2);
}

/* Compare mode active state - dim non-compared items */
.lc-timeline--compare-active
	.lc-timeline-item:not(.lc-timeline-item--compare-from):not(.lc-timeline-item--compare-to) {
	opacity: 0.5;
}

.lc-timeline--compare-active
	.lc-timeline-item:not(.lc-timeline-item--compare-from):not(.lc-timeline-item--compare-to):hover {
	opacity: 0.75;
}

