import { browser } from '$app/env';
import { get, writable } from 'svelte/store';

export type ThemeMode = 'light' | 'dark';

const STORAGE_KEY = 'lawcast-theme';
const DARK_THEME_COLOR = '#242526';
const LIGHT_THEME_COLOR = '#ffffff';

function readSavedTheme(): string | null {
	try {
		return window.localStorage.getItem(STORAGE_KEY);
	} catch {
		return null;
	}
}

function isThemeMode(value: string | null): value is ThemeMode {
	return value === 'light' || value === 'dark';
}

function getSystemTheme(): ThemeMode {
	if (!browser) {
		return 'light';
	}

	return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function readInitialTheme(): ThemeMode {
	if (!browser) {
		return 'light';
	}

	const savedTheme = readSavedTheme();
	if (isThemeMode(savedTheme)) {
		return savedTheme;
	}

	// The system preference can change after the inline paint script but
	// before this module installs the media-query listener.
	return getSystemTheme();
}

let paletteFrame: number | null = null;

function syncTheme(theme: ThemeMode) {
	if (!browser) {
		return;
	}

	const root = document.documentElement;
	if (root.dataset.theme !== theme) {
		// Apply foreground and surface tokens atomically, retaining transform/opacity motion.
		root.setAttribute('data-theme-changing', '');
		if (paletteFrame !== null) cancelAnimationFrame(paletteFrame);
		paletteFrame = requestAnimationFrame(() => {
			paletteFrame = requestAnimationFrame(() => {
				root.removeAttribute('data-theme-changing');
				paletteFrame = null;
			});
		});
	}
	root.dataset.theme = theme;
	document.documentElement.style.colorScheme = theme;

	const metaThemeColor = document.querySelector('meta[name="theme-color"]');
	metaThemeColor?.setAttribute('content', theme === 'dark' ? DARK_THEME_COLOR : LIGHT_THEME_COLOR);
}

const initialTheme = readInitialTheme();
syncTheme(initialTheme);

const themeStore = writable<ThemeMode>(initialTheme);

if (browser) {
	const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
	const handleSystemThemeChange = (event: MediaQueryListEvent) => {
		if (isThemeMode(readSavedTheme())) {
			return;
		}

		const nextTheme = event.matches ? 'dark' : 'light';
		syncTheme(nextTheme);
		themeStore.set(nextTheme);
	};

	mediaQuery.addEventListener('change', handleSystemThemeChange);
}

export const theme = {
	subscribe: themeStore.subscribe,
	set(nextTheme: ThemeMode) {
		if (browser) {
			try {
				window.localStorage.setItem(STORAGE_KEY, nextTheme);
			} catch {
				// Theme changes still apply when persistence is unavailable.
			}
		}

		syncTheme(nextTheme);
		themeStore.set(nextTheme);
	},
	toggle() {
		const nextTheme = get(themeStore) === 'dark' ? 'light' : 'dark';
		this.set(nextTheme);
	}
};

